mapper.select:
SELECT x.month FROM (
  SELECT m.work_ym AS month FROM asgn.asgn a JOIN asgn.asgn_mth m ON m.asgn_id=a.asgn_id
    WHERE a.prj_id=#{id} AND a.asgn_stts_cd!='CANCELLED'
  UNION SELECT e.expns_ym FROM cst.drct_expns e WHERE e.prj_id=#{id}
  UNION SELECT s.cst_ym FROM cst.cst_aloc s WHERE s.prj_id=#{id}
) x WHERE x.month <= #{month} ORDER BY x.month
